def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    if n == 1:
        print(0)
        return

    edges = []
    pos = 2
    for _ in range(m):
        u, v, weight = data[pos], data[pos + 1], data[pos + 2]
        edges.append((weight, u, v))
        pos += 3
    edges.sort()

    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for weight, u, v in edges:
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            if size[root_u] < size[root_v]:
                root_u, root_v = root_v, root_u
            parent[root_v] = root_u
            size[root_u] += size[root_v]
            if find(1) == find(n):
                print(weight)
                return

    print(-1)


if __name__ == "__main__":
    main()
